195	          <Footer />
196	        </PostHogProvider>
197	
198	        {/* ── Google Analytics (gtag.js) — G-VSPBSV4406 ──────── */}
199	        <Script
200	          src="https://www.googletagmanager.com/gtag/js?id=G-VSPBSV4406"
201	          strategy="afterInteractive"
202	        />
203	        <Script
204	          id="gtag-init"
205	          strategy="afterInteractive"
206	          dangerouslySetInnerHTML={{
207	            __html: `
208	              window.dataLayer = window.dataLayer || [];
209	              function gtag(){dataLayer.push(arguments);}
210	              gtag('js', new Date());
211	              gtag('config', 'G-VSPBSV4406');
212	            `,
213	          }}
214	        />
215	
216	        {/* ── Microsoft Clarity — v2sdjrzf16 ─────────────────── */}
217	        <Script
218	          id="clarity-init"
219	          strategy="afterInteractive"
220	          dangerouslySetInnerHTML={{
221	            __html: `
222	              (function(c,l,a,r,i,t,y){
223	                c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
224	                t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
225	                y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
226	              })(window, document, "clarity", "script", "v2sdjrzf16");
227	            `,
228	          }}
229	        />
230	
231	        {/* ── Contentsquare ──────────────────────────────────── */}
232	        <Script
233	          src="https://t.contentsquare.net/uxa/82f0998b73803.js"
234	          strategy="afterInteractive"
235	        />
236	
237	        {/* ── Chatwoot (hardcoded token from Webflow) ─────────── */}
238	        <Script
239	          id="chatwoot-sdk"
240	          strategy="afterInteractive"
241	          dangerouslySetInnerHTML={{
242	            __html: `
243	              if (window.self === window.top) {
244	                (function(d,t) {
245	                  var BASE_URL="https://app.chatwoot.com";
246	                  var g=d.createElement(t),s=d.getElementsByTagName(t)[0];
247	                  g.src=BASE_URL+"/packs/js/sdk.js";
248	                  g.async=true;
249	                  s.parentNode.insertBefore(g,s);
250	                  g.onload=function(){
251	                    window.chatwootSDK.run({
252	                      websiteToken: 'i6RsELa1Smu1Gp6ayBrvTiQj',
253	                      baseUrl: BASE_URL
254	                    })
255	                  }
256	                })(document,"script");
257	              }
258	            `,
259	          }}
260	        />
261	
262	        {/* ── Chatwoot aria-label fix ─────────────────────────── */}
263	        <Script
264	          id="chatwoot-aria"
265	          strategy="afterInteractive"
266	          dangerouslySetInnerHTML={{
267	            __html: `
268	              function fixChatwootAria() {
269	                var openBtn = document.querySelector('.woot-widget-bubble:not(.woot--close)');
270	                var closeBtn = document.querySelector('.woot-widget-bubble.woot--close');
271	                if (openBtn && !openBtn.getAttribute('aria-label')) openBtn.setAttribute('aria-label', 'Open chat window');
272	                if (closeBtn && !closeBtn.getAttribute('aria-label')) closeBtn.setAttribute('aria-label', 'Close chat window');
273	              }
274	              fixChatwootAria();
275	              new MutationObserver(fixChatwootAria).observe(document.body, { childList: true, subtree: true });
276	            `,
277	          }}
278	        />
279	      </body>
280	    </html>
281	  );
282	}
