34	}: {
35	  params: Promise<{ slug: string }>;
36	}) {
37	  const { slug } = await params;
38	  const post = BLOG_POSTS.find((p) => p.slug === slug);
39	  if (!post) notFound();
40	
41	  // Related posts: same category, excluding current
42	  const related = BLOG_POSTS.filter(
43	    (p) => p.slug !== post.slug && p.category === post.category,
