46	  // If fewer than 3 related, fill from other posts
47	  const relatedPosts =
48	    related.length >= 2
49	      ? related
50	      : [
51	          ...related,
52	          ...BLOG_POSTS.filter(
53	            (p) =>
54	              p.slug !== post.slug &&
55	              !related.find((r) => r.slug === p.slug),
56	          ).slice(0, 3 - related.length),
57	        ];
58	
59	  const breadcrumbs = breadcrumbSchema([
60	    { name: "Blog", path: "/blog" },
