3	type SchemaObject = Record<string, unknown>;
4	
5	interface JsonLdProps {
6	  data: SchemaObject | SchemaObject[];
7	  id?: string;
8	}
9	
10	/**
11	 * Render a JSON-LD <script> block.
12	 * Pass a single schema object or an array (will be emitted as @graph).
13	 */
14	export function JsonLd({ data, id }: JsonLdProps) {
15	  const payload = Array.isArray(data)
16	    ? { "@context": "https://schema.org", "@graph": data }
17	    : data;
18	
19	  return (
20	    <script
21	      id={id}
22	      type="application/ld+json"
23	      dangerouslySetInnerHTML={{ __html: JSON.stringify(payload) }}
24	    />
25	  );
26	}
