28	export interface BreadcrumbItem {
29	  name: string;
30	  path: string;
31	}
32	
33	/**
34	 * Build BreadcrumbList JSON-LD from a Home → … → current path.
35	 */
36	export function breadcrumbSchema(items: BreadcrumbItem[]): SchemaObject {
37	  const list = [
38	    { name: "Home", path: "/" },
39	    ...items,
40	  ];
41	  return {
42	    "@context": "https://schema.org",
43	    "@type": "BreadcrumbList",
44	    itemListElement: list.map((item, idx) => ({
45	      "@type": "ListItem",
46	      position: idx + 1,
47	      name: item.name,
48	      item: `${SITE_CONFIG.url}${item.path}`,
49	    })),
50	  };
51	}
